#Requires -Version 7.0
[CmdletBinding(SupportsShouldProcess)]
param()
$ErrorActionPreference='Stop'
$repo='<repo>'
$dir=Join-Path $repo 'docs/evidence/release15/conflict-retirement'
function Get-Pin([string]$Path){[pscustomobject]@{path=$Path;sha256=(Get-FileHash -LiteralPath $Path).Hash}}
$mock=Get-Content -LiteralPath (Join-Path $dir 'mock-20261030T192055/receipt.json') -Raw|ConvertFrom-Json
$real=Get-Content -LiteralPath (Join-Path $dir 'real-20261030T192330/receipt.json') -Raw|ConvertFrom-Json
$check=Get-Content -LiteralPath (Join-Path $dir 'source-check.json') -Raw|ConvertFrom-Json
foreach($run in @($mock,$real)){
 if($run.exitCode -or $run.cases -ne 162 -or $run.failed -or $run.skipped -or $run.negativeControls -ne 81){throw 'Actual native gate differs from required isolated scope'}
 if((Get-FileHash -LiteralPath $run.junit).Hash -cne $run.junitSha256){throw 'Native XML drift'}
 foreach($pin in $run.sourcePins){if((Get-FileHash -LiteralPath $pin.copy).Hash -cne $pin.sha256){throw 'Retained source drift'}}
}
if($check.lintExit -or $check.diffExit -or $check.typecheckExit -or -not $check.priorCaseAssertionsAndInputsUnchanged -or -not $check.priorContractOnlyModeAndCallbackTypes){throw 'Final source check did not pass'}
foreach($pin in $check.sourcePins){if((Get-FileHash -LiteralPath (Join-Path $repo $pin.path)).Hash -cne $pin.sha256){throw 'Actual source differs from final checked source'}}
$evidence=@('plan.md','effective-requirements.json','source-check.json','source-check-producer.ps1','mock-20261030T192055/receipt.json','mock-20261030T192055/unit.xml','mock-20261030T192055/unit.log','mock-20261030T192055/producer.ps1','real-20261030T192330/receipt.json','real-20261030T192330/unit.xml','real-20261030T192330/unit.log','real-20261030T192330/producer.ps1')
$receipt=[ordered]@{recordedAt=(Get-Date -Format s);classification='Authorized test-harness repair, same-family isolated proof, not hostile approval';parentSessionId='Codex-20261027T100516Z-plugin-session';parentRequestId='req-20261030T203656Z-cline-beam-release';sessionId='Codex-20261030T200118Z-plugin-session';requestId='req-20261031T001418Z-conflict-retirement-repair';baseRevision='af6ee6fe0c4a288ac23f570a4fa6a94d697d8127';dirtySourceQualified=$true;mock=@{started=$mock.startedAt;finished=$mock.finishedAt;cases=162;failed=0;skipped=0;negativeControls=81};real=@{started=$real.startedAt;finished=$real.finishedAt;cases=162;failed=0;skipped=0;negativeControls=81};newCases=38;retainedPriorCases=124;sourcePins=$check.sourcePins;sameOracle=$check.sameOracle;evidence=@($evidence|ForEach-Object {Get-Pin (Join-Path $dir $_)});priorAssertionPreservation='Original124 assertions/inputs retained. Existing AckMode and retired callback parameter types extended; old independent provider forwards response at its two existing retired call sites. These two files are not claimed byte-identical.';chronology='Plan initially named18 pairs; parent/capacity requested busy fresh guard and started-probe ownership plus combined-error preservation. Actual tests added19 pairs before first green mock, while protected five implementation/type/adaptor pins remained frozen. Plan count reconciled afterward before real helper edit. All native histories preserved.';intermediateTypecheckFailures=$check.retainedIntermediateTypecheckFailures;finalTypecheckExit=0;scopedBiomeExit=0;scopedBiomeWarnings=15;scopedDiffExit=0;failedMatrixPreserved='frozen-af6ee6f actual2passed,1failed at4players round3/11driver-result solves,11skipped. This isolated repair does not supersede or hide that failure.';knownCausality='Native stack proves fresh-mode retirement mismatch; final snapshots do not show the transient throwing state. No application/network/load/latency cause or fix established.';runtimeLimits='Scripted probe/until/classifier/commit composition is tested; real readCommandUi DOM extraction, Playwright polling deadline behavior and browser adapter wiring need the next frozen actual UI runs. No game/schema/dependency/policy/cap/timeouts changed. Strict remains fail-only success acknowledgement/four conflicts; matrix retains12attempts. Unknown fresh pending remains rejected even while busy. Retire checks actual409 then waits idle/pending-free/version without replay.';observationLimits='New409 observations preserve exact CapturedCommand/Request in the isolated oracle. Actual artifacts reuse safe player-index and UUID/action/status/version state fields, with null conflict responseVersion. A classifier failure may occur before a callback records its state. No answer/raw payload/token persistence or historical actor inference.';rootRequiredNext='Freeze current test source and run complete required five-lane chain; inspect actual UI/latency and all native evidence; only then eligible independent ClineBeamHigh review. No status/satisfaction changes.';requirementsMutated=$false;applicationSourceEdited=$false;actualUiBuildModelsProvidersRunByThisAgent=$false;accuracy=99;completeness=98;ratingQualification='Scoped isolated repair evidence and source readback only, not release acceptance.'}
if(-not $PSCmdlet.ShouldProcess($dir,'Retain consolidated truthful retirement repair receipt and producer')){return}
$path=Join-Path $dir 'receipt.json';if(Test-Path -LiteralPath $path){throw 'Preserve previous consolidated receipt'}
$receipt|ConvertTo-Json -Depth 15|Set-Content -LiteralPath $path
$copy=Join-Path $dir 'receipt-producer.ps1';Copy-Item -LiteralPath $PSCommandPath -Destination $copy
if((Get-FileHash -LiteralPath $copy).Hash -cne (Get-FileHash -LiteralPath $PSCommandPath).Hash){throw 'Receipt producer copy mismatch'}
Get-Pin $path|ConvertTo-Json
Get-Date -Format s
